using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 bool CancelHoldingSame=>FlowCase=="dircancelheld-same";
 bool CancelHoldingFuture=>FlowCase=="dircancelheld-future";
 bool CancelHoldingNotice=>FlowCase=="dircancelheld-notice";
 TroopDispatch HeldCancellation()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.First();
 TroopReceipt HeldCancellationInitial()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.First();
 UnitHeldTransfer CancellationPaperTransfer()=>game!.Session.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.First(t=>t.Action==NewMilitaryAction.DeliverHeldUnitDirectiveCancellation);
 UnitDirectiveCancelLateReceipt CancellationPaperAck()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Holding!.Outcomes.Single();
 async Task DirectiveCancelHoldingStep(int n){await Frame();var s=game!.Session;
  if(n==0){game.SelectKnownMilitary(NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[1]);game.ChooseMilitary(NewMilitaryAction.RemoteRecall);game.Advance(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);game.Press("unit-directive-hold");if(CancelHoldingFuture)game.ExerciseRetainedDirectiveCancelAt(s.Seconds+180);else game.Press("unit-directive-cancel-retain");Check(!game.ButtonEnabled("unit-directive-cancel-handoff"),"dispatch does not create returned paper");}
  if(n==1){game.Advance(HeldCancellation().DueAt);Check(!HeldCancellationInitial().Delivered&&!NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds).Any(h=>h.Message==HeldCancellation().Message),"missed visit alone creates no local original");}
  if(n==2){game.Advance(HeldCancellationInitial().ReplyDueAt);game.Advance(Math.Max(s.Seconds,ArmyEnd()+2));Check(game.ButtonEnabled("unit-directive-cancel-handoff"),"real retained cancellation returned to nearby original holder");Check(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds).Any(h=>h.Message==HeldCancellation().Message),"actual returned paper is listed");}
  if(n==3){game.Press("unit-directive-cancel-handoff");if(CancelHoldingSame){game.Press("unit-directive-cancel-retry");var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();Check(copy.Message==HeldCancellation().Message&&copy.DueAt==CancellationPaperTransfer().DueAt,"copy and retained original arrive together");}Check(!game.ButtonEnabled("unit-directive-cancel-handoff"),"one physical attempt cannot be scheduled twice");}
  if(n==4){game.Advance(CancellationPaperTransfer().DueAt);var w=s.DiagnosticSnapshot();Check(CancellationPaperAck().Received&&w.Messaging.Receipts.Count(r=>r.MessageId==HeldCancellation().Message)==1,"real original has one formal receipt even with a copy");Check(!NewGameMilitary.ReceiptConfirmedToSender(w,HeldCancellation().Message,s.PlayerControl.Value),"remote late receipt is not sender knowledge");if(CancelHoldingFuture)Check(w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Length==0,"late receipt retains original future requested time");else Check(w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Id==HeldCancellation().Id,"late original cancellation has one canonical effect");if(CancelHoldingNotice){var a=NewGameMilitary.Anchor(w);game.ExercisePersonalMove(new(a.X-40000,a.Y));}}
  if(n==5){game.Advance(CancellationPaperAck().DueAt);var w=s.DiagnosticSnapshot();if(CancelHoldingNotice){Check(!MessageFlow.Knows(w.Messaging,CancellationPaperAck().ReplyMessage!,s.PlayerControl.Value)&&NewGameMilitary.HeldPapers(w,s.Seconds).Any(h=>h.Message==CancellationPaperAck().ReplyMessage),"actual late acknowledgment misses person and remains held");Check(!NewGameMilitary.ReceiptConfirmedToSender(w,HeldCancellation().Message,s.PlayerControl.Value),"missed late acknowledgment cannot confirm remote receipt");}else Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,HeldCancellation().Id).Contains(CancelHoldingFuture?"効力時刻を待つ":"未実行の対象原本を取消"),"physically received late acknowledgment updates selected cancellation result");}
  if(n==6){if(CancelHoldingFuture){long at=s.DiagnosticSnapshot().NewMilitary!.Requests.Single(q=>q.Input.Id==HeldCancellation().Id).Input.DirectiveCancellation!.EffectiveAt;game.Advance(at);Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),HeldCancellation().Id).Contains("効力時刻を待つ"),"future effect is unknown until actual notice arrives");}else if(CancelHoldingNotice){game.Advance(Math.Max(s.Seconds,PersonEnd()+1));game.ExercisePersonalMove(CancellationPaperAck().Destination);game.Advance(PersonEnd()+1);game.ChooseMilitary(NewMilitaryAction.TakeHeldReply);Check(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().Message==CancellationPaperAck().ReplyMessage,"only actual nearby late acknowledgment can be recovered");}else game.Advance(s.Seconds+3);}
  if(n==7){if(CancelHoldingFuture){var notice=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Notices.Single();Check(notice.Destination==CancellationPaperTransfer().Origin,"future result returns to actual handoff origin");game.Advance(notice.DueAt);}else if(CancelHoldingNotice)game.Advance(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt+1);else game.Press("rotate");var w=s.DiagnosticSnapshot();Check(!HeldCancellationInitial().Delivered&&w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Length==1,"initial loss is immutable and cancellation effect is singular");Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,HeldCancellation().Id).Contains("未実行の対象原本を取消"),"person eventually learns only the physically delivered result");}
  game.Refresh();Check(game.RecognitionModelsMatch(),"retained cancellation 3D matches actual known world at"+n);game.Press("save");await WaitSave();
 }
 async Task BeginDirectiveCancelHoldingContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<=4;n++)await RecognitionStep(n);for(int n=0;n<8;n++){await DirectiveCancelHoldingStep(n);game!.SaveCheckpoint("cancelheld"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreDirectiveCancelHolding(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,row=>row.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<8;n++){game!.LoadCheckpoint("cancelheld"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"same retained cancellation selected root knowledge world and3D after restore"+n);await Capture("restored-s"+n,true);for(int k=n+1;k<8;k++)await DirectiveCancelHoldingStep(k);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same physical cancellation future from"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_DIRECTIVE_CANCEL_HOLDING_RESTORED "+n);}}
 async Task RunDirectiveCancelHoldingChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreDirectiveCancelHolding();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-directive-cancel-holding-film")){game!.LoadCheckpoint("cancelheld3");game.Press("auto");string dir=Path.Combine(TestOutput,"film",TestKey??"normal");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"cancel-held-"+n.ToString("D3")+".png"));}game.Press("pause");File.WriteAllText(Path.Combine(TestOutput,"film-manifest.json"),System.Text.Json.JsonSerializer.Serialize(new{Directory=Path.GetRelativePath(TestOutput,dir),Frames=180,Checkpoint=3,Action="real-cancellation-original-and-copy-arrive"}));}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_DIRECTIVE_CANCEL_HOLDING_PASSED "+FlowCase);}
}
